mapper.insert:
INSERT INTO ENROLLMENT ( ENROLLMENT_ID, MEMBER_ID, COURSE_ID, STATUS, START_DATE, COMPLETED_DATE ) SELECT (SELECT NVL(MAX(ENROLLMENT_ID), 0) FROM ENROLLMENT) + ROW_NUMBER() OVER (ORDER BY M.MEMBER_ID), M.MEMBER_ID, #{courseId}, 'Y', SYSDATE, NULL FROM MEMBER M WHERE M.STATUS = 'Y' AND M.ROLE = 'N'
AND M.DEPARTMENT_ID = #{targetValue}
AND M.POSITION_ID = #{targetValue}
AND 1 = 1
AND NOT EXISTS ( SELECT 1 FROM ENROLLMENT E WHERE E.MEMBER_ID = M.MEMBER_ID AND E.COURSE_ID = #{courseId} )

mapper.select:
SELECT NVL(MAX(CHAPTER_ORDER), 0) + 1
FROM CHAPTER
WHERE COURSE_ID = #{courseId}

mapper.delete:
DELETE FROM CHAPTER_PROGRESS
WHERE CHAPTER_ID IN (
	SELECT CHAPTER_ID
	FROM CHAPTER
	WHERE COURSE_ID = #{value}
)

mapper.select:
